$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'experiment-1-22-native-log-capture.ps1')
$root=Join-Path $env:TEMP ('exp122-capture-fixtures-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory -Force $root
try {
  try{$a=Invoke-Exp122PostStopLogCapture -RunId 'FIXTURE-A' -ContainerId 'fixture' -ApplicationDirectory (Join-Path $root 'a') -TimeoutSeconds 2 -ContainerStateAtCapture 'stopped' -Executable 'powershell.exe' -Arguments @('-NoProfile','-Command','Write-Output fixture; exit 0')}catch{$a=Get-Content (Join-Path $root 'a/docker-logs-capture.json') -Raw|ConvertFrom-Json;if($a.captureStatus-ne'APPLICATION_LOG_CAPTURE_PASSED'){throw "fixture A failed: $($a|ConvertTo-Json -Compress)"}};if($a.captureStatus-ne'APPLICATION_LOG_CAPTURE_PASSED'){throw 'fixture A failed'};Write-Output 'fixture-A normal exit PASS'
  $timeout=$false;try{Invoke-Exp122PostStopLogCapture -RunId 'FIXTURE-B' -ContainerId 'fixture' -ApplicationDirectory (Join-Path $root 'b') -TimeoutSeconds 1 -ContainerStateAtCapture 'stopped' -Executable 'powershell.exe' -Arguments @('-NoProfile','-Command','Write-Output partial; Start-Sleep -Seconds 5')}catch{$timeout=$true};if(-not$timeout){throw 'fixture B did not timeout'};$b=Get-Content (Join-Path $root 'b/docker-logs-capture.json') -Raw|ConvertFrom-Json;if($b.captureStatus-ne'APPLICATION_LOG_CAPTURE_TIMEOUT'-or$b.timedOut-ne$true){throw 'fixture B metadata mismatch'};Write-Output 'fixture-B timeout PASS'
  $name='exp122-post-stop-fixture-'+[guid]::NewGuid().ToString('N');$id=(docker run -d --name $name alpine:3.20 sh -c 'echo stopped-fixture; sleep 60').Trim();if(-not$id){throw 'fixture C container start failed'};docker stop -t 1 $name|Out-Null;$state=(docker inspect --format '{{.State.Status}}' $name).Trim();if($state -match 'running'){throw 'fixture C container still running'};$c=Invoke-Exp122PostStopLogCapture -RunId 'FIXTURE-C' -ContainerId $id -ApplicationDirectory (Join-Path $root 'c') -TimeoutSeconds 5 -ContainerStateAtCapture $state;if($c.captureStatus-ne'APPLICATION_LOG_CAPTURE_PASSED'-or$c.containerStateAtCapture-match'running'){throw 'fixture C capture failed'};Write-Output 'fixture-C stopped-container PASS'
  Write-Output 'EXP122_CAPTURE_FIXTURES_PASS'
} finally {if($name){docker rm -f $name|Out-Null};Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue}
